<script>
(function() {
  "use strict";

  // ── Step data ──────────────────────────────────────────────
  const STEPS = [
    {
      label: "Step 0 — The User Composes a Message",
      infoTitle: "Step 0 — The User Composes a Message",
      infoText: 'You type a question into <strong>AIVA\'s Console</strong> — the browser-based chat UI. The Console doubles as an HTTP/WebSocket server, so your message can travel into the robot\'s nervous system without leaving the room.',
      draw: drawStep0
    },
    {
      label: "Step 1 — Console Encodes &amp; Publishes via rosbridge",
      infoTitle: "Step 1 — Encoding &amp; Publishing",
      infoText: 'Console applies reversible <strong>Cypher encoding</strong> (not encryption) to your message, then publishes it through <code>rosbridge</code> onto the ROS 2 topic <code>/telepathic/stimulus</code>. Think of Cypher as a sealed envelope — it scrambles the letters so eavesdroppers can\'t read them, but AIVA holds the key.',
      draw: drawStep1
    },
    {
      label: "Step 2 — Telepathy Receptor Decodes the Request",
      infoTitle: "Step 2 — Decoding at the Receptor",
      infoText: 'The <code>telepathy_receptor</code> ROS node listens on <code>/telepathic/stimulus</code>, decodes the Cypher text, and hands the clean request to the <strong>Interactive</strong> Python library. This node is the bridge between ROS 2\'s nervous system and AIVA\'s conversational brain.',
      draw: drawStep2
    },
    {
      label: "Step 3 — Interactive Assembles Persona, Profile &amp; Memory",
      infoTitle: "Step 3 — Assembling Grace's Context",
      infoText: 'Interactive assembles Grace\'s <strong>persona</strong>, the current <strong>time</strong>, your <strong>user profile</strong>, and recent conversation history from <strong>Memory</strong> — an in-process Python library backed by SQLite. By default, up to eight recent exchanges are included. (Older exchanges are stored, but semantic retrieval isn\'t in this chat path yet.)',
      draw: drawStep3
    },
    {
      label: "Step 4 — llama.cpp Router Runs Nymphaea RP &amp; Streams",
      infoTitle: "Step 4 — The Model Responds",
      infoText: 'Interactive calls the local <code>llama.cpp</code> OpenAI-compatible router at <code>/v1/chat/completions</code>, selecting <strong>nymphaea-rp</strong> for the front end. The model streams text deltas back — word by word — like someone thinking out loud in real time.',
      draw: drawStep4
    },
    {
      label: "Step 5 — Response Returns &amp; Console Streams the Reply",
      infoTitle: "Step 5 — Decoding &amp; Delivering the Reply",
      infoText: 'The response returns as Cypher-encoded text on <code>/telepathic/response</code>. The Console decodes it and streams the restored text to your browser, so Grace\'s reply appears character by character right in the chat.',
      draw: drawStep5
    },
    {
      label: "Step 6 — Memory Saves the Completed Exchange",
      infoTitle: "Step 6 — Memory Persists the Exchange",
      infoText: 'Memory saves the completed conversation exchange to its SQLite store, so Grace can remember this chat next time. The <code>voyage-4-nano</code> embeddings router exists but is <strong>not wired into this chat path</strong> yet — semantic retrieval is on the roadmap, not in the current implementation.',
      draw: drawStep6
    }
  ];

  // ── State ──────────────────────────────────────────────────
  let currentStep = 0;
  let playing = false;
  let playTimer = null;
  const PLAY_INTERVAL = 2800;
  const TOTAL_STEPS = 7; // 0..6

  // ── DOM refs ───────────────────────────────────────────────
  const stepLabel = document.getElementById('step-label');
  const stageContent = document.getElementById('stage-content');
  const infoTitle = document.getElementById('info-title');
  const infoText = document.getElementById('info-text');
  const nextBtn = document.getElementById('next');
  const resetBtn = document.getElementById('reset');
  const playBtn = document.getElementById('play');
  const dots = document.querySelectorAll('.dot');

  // ── Drawing helpers ────────────────────────────────────────
  function clearStage() {
    stageContent.innerHTML = '';
  }

  function el(tag, attrs, children) {
    const node = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v !== undefined && v !== null) node.setAttribute(k, v);
    }
    if (children) {
      if (typeof children === 'string') {
        const t = document.createTextNode(children);
        node.appendChild(t);
      } else if (children.length !== undefined) {
        for (const c of children) {
          node.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
        }
      } else {
        node.appendChild(children);
      }
    }
    return node;
  }

  function text(x, y, content, attrs) {
    return el('text', { x, y, ...attrs }, content);
  }

  function rect(x, y, w, h, attrs) {
    return el('rect', { x, y, width: w, height: h, ...attrs });
  }

  function circle(cx, cy, r, attrs) {
    return el('circle', { cx, cy, r, ...attrs });
  }

  function line(x1, y1, x2, y2, attrs) {
    return el('line', { x1, y1, x2, y2, ...attrs });
  }

  function path(d, attrs) {
    return el('path', { d, ...attrs });
  }

  function group(attrs, children) {
    return el('g', attrs, children);
  }

  // ── Character: User (cartoon) ──────────────────────────────
  function drawUser(cx, cy, scale, opts = {}) {
    const s = scale || 1;
    const g = group({ class: 'float-anim' });
    const skin = '#fcd9b6';
    const hair = '#5c3a1e';
    const shirt = '#6c8cff';
    const pants = '#2a2d3a';

    // Body
    g.appendChild(rect(cx - 22*s, cy + 10*s, 44*s, 50*s, { rx: 8, fill: shirt }));
    // Arms
    g.appendChild(rect(cx - 34*s, cy + 14*s, 12*s, 30*s, { rx: 5, fill: skin }));
    g.appendChild(rect(cx + 22*s, cy + 14*s, 12*s, 30*s, { rx: 5, fill: skin }));
    // Head
    g.appendChild(circle(cx, cy - 14*s, 20*s, { fill: skin }));
    // Hair
    g.appendChild(path(`M ${cx-20*s} ${cy-22*s} Q ${cx-18*s} ${cy-36*s} ${cx} ${cy-34*s} Q ${cx+18*s} ${cy-36*s} ${cx+20*s} ${cy-22*s} L ${cx+20*s} ${cy-18*s} L ${cx-20*s} ${cy-18*s} Z`, { fill: hair }));
    // Eyes
    g.appendChild(circle(cx - 7*s, cy - 16*s, 2.5*s, { fill: '#333' }));
    g.appendChild(circle(cx + 7*s, cy - 16*s, 2.5*s, { fill: '#333' }));
    // Mouth
    g.appendChild(path(`M ${cx-6*s} ${cy-6*s} Q ${cx} ${cy-1*s} ${cx+6*s} ${cy-6*s}`, { fill: 'none', stroke: '#c0392b', 'stroke-width': 1.8 }));
    // Legs
    g.appendChild(rect(cx - 18*s, cy + 56*s, 14*s, 28*s, { rx: 4, fill: pants }));
    g.appendChild(rect(cx + 4*s, cy + 56*s, 14*s, 28*s, { rx: 4, fill: pants }));
    // Feet
    g.appendChild(rect(cx - 20*s, cy + 80*s, 16*s, 8*s, { rx: 3, fill: '#1a1d27' }));
    g.appendChild(rect(cx + 4*s, cy + 80*s, 16*s, 8*s, { rx: 3, fill: '#1a1d27' }));

    if (opts.label) {
      g.appendChild(text(cx, cy + 100*s, opts.label, { 'text-anchor': 'middle', fill: '#8b8f9c', 'font-size': '11', 'font-family': 'system-ui' }));
    }
    return g;
  }

  // ── Character: AIVA/Grace (cartoon robot) ────────────────────
  function drawGrace(cx, cy, scale, opts = {}) {
    const s = scale || 1;
    const g = group({ class: opts.class || '' });
    const bodyGrad = 'url(#accent-grad)';
    const eyeGlow = '#4ade80';

    // Antenna
    g.appendChild(line(cx, cy - 40*s, cx, cy - 52*s, { stroke: '#6c8cff', 'stroke-width': 2.5 }));
    g.appendChild(circle(cx, cy - 55*s, 4*s, { fill: '#f472b6', class: 'pulse-anim' }));

    // Head
    g.appendChild(rect(cx - 28*s, cy - 40*s, 56*s, 44*s, { rx: 10, fill: '#2a2d3a', stroke: '#6c8cff', 'stroke-width': 1.5 }));

    // Face screen
    g.appendChild(rect(cx - 22*s, cy - 34*s, 44*s, 32*s, { rx: 6, fill: '#141620' }));

    // Eyes (digital)
    const eyeY = cy - 20*s;
    g.appendChild(rect(cx - 12*s, eyeY - 3*s, 8*s, 6*s, { rx: 2, fill: eyeGlow, class: 'pulse-anim' }));
