  // ── Arrow with label ───────────────────────────────────────
  function drawArrow(x1, y1, x2, y2, color, label, opts = {}) {
    const g = group();
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2;
    g.appendChild(line(x1, y1, x2, y2, { stroke: color || '#6c8cff', 'stroke-width': 2, 'marker-end': 'url(#arrowhead)', opacity: opts.opacity || 0.8 }));
